// Binary assets, base64 - GitHub web-upload workaround. Regenerate with cad/build_b64.py
const PIP_GLB_B64="";
const PIP_RENDERS={pip_front:"data:image/jpeg;base64,",pip_threequarter:"data:image/jpeg;base64,",pip_side:"data:image/jpeg;base64,",pip_back:"data:image/jpeg;base64,",pip_top:"data:image/jpeg;base64,"};
function hydrateB64(){
  document.querySelectorAll("img[data-b64]").forEach(im=>{ if(PIP_RENDERS[im.dataset.b64]) im.src=PIP_RENDERS[im.dataset.b64]; });
}
function glbBytes(){ const b=atob(PIP_GLB_B64); const a=new Uint8Array(b.length); for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i); return a.buffer; }
